<script lang="ts">
 import {focusDialog} from '../utils/focusDialog';
 import {untrack} from 'svelte';
 import {X,Download,FolderOutput} from '@lucide/svelte';
 import type {Job} from '../types';
 let {job,selected,onclose,onexport}:{job:Job;selected:string[];onclose:()=>void;onexport:(options:any)=>void}=$props();
 let format=$state(untrack(()=>job.settings.format)),quality=$state(untrack(()=>job.settings.jpeg_quality)),preference=$state(untrack(()=>job.settings.preference)),resolution=$state(untrack(()=>job.settings.resolution)),dpi=$state(untrack(()=>job.settings.dpi)),scope=$state(untrack(()=>selected.length?'selected':'accepted')),naming=$state('page'),prefix=$state(''),from=$state(1),to=$state(untrack(()=>job.total)),metadata=$state(untrack(()=>job.settings.preserve_metadata));
 function submit(){onexport({format,jpeg_quality:quality,preference,resolution,dpi,naming,prefix,preserve_metadata:metadata,page_from:from,page_to:to,ids:scope==='selected'?selected:[],statuses:scope==='all'||scope==='selected'?['accepted','review','rejected']:scope==='review'?['review']:['accepted']});}
</script>
<div class="modal-backdrop"><div class="modal export-modal" role="dialog" use:focusDialog={onclose} aria-modal="true" aria-label="Export photographs" tabindex="-1"><div class="modal-head"><div><h2>Export photographs</h2><p>Original detail. Individual files. Ready for your workflow.</p></div><button class="icon-button" aria-label="Close export" onclick={onclose}><X size={20}/></button></div><div class="modal-body">
 <label class="field">Photographs<select bind:value={scope}><option value="accepted">All accepted ({job.counts.accepted||0})</option><option value="review">Needs review ({job.counts.review||0})</option><option value="selected" disabled={!selected.length}>Selected ({selected.length})</option><option value="all">All, including rejected ({job.photographs})</option></select></label>
 <div class="form-grid"><label class="field">From page<input type="number" min="1" max={job.total} bind:value={from}/></label><label class="field">To page<input type="number" min={from} max={job.total} bind:value={to}/></label><label class="field">Output format<select bind:value={format}><option value="png">PNG · lossless</option><option value="jpg">JPEG</option><option value="original">Original when possible</option></select></label><label class="field">Image composition<select bind:value={preference}><option value="auto">Automatic · visible crop</option><option value="source">Complete embedded source</option><option value="displayed">As displayed in PDF</option></select></label></div>
 {#if format==='jpg'}<label class="field">JPEG quality · {quality}<input type="range" min="1" max="100" bind:value={quality}/></label>{/if}
 <div class="form-grid"><label class="field">Resolution<select bind:value={resolution}><option value="source">Original / source-aware</option><option value="dpi">Target DPI (no raster upscaling)</option></select></label><label class="field">Render fallback / target DPI<input type="number" min="72" max="1200" step="1" list="dpi-options" bind:value={dpi}/><datalist id="dpi-options">{#each [150,200,300,400,600] as v}<option value={v}></option>{/each}</datalist></label><label class="field">File naming<select bind:value={naming}><option value="page">Page and photograph</option><option value="sequential">Sequential numbering</option><option value="source">Embedded image identifier</option><option value="document">Document + page</option></select></label><label class="field">Filename prefix<input bind:value={prefix} placeholder="Optional"/></label></div>
 <label class="check-field"><input type="checkbox" bind:checked={metadata}/>Preserve available image metadata</label><div class="notice"><FolderOutput size={18}/><span>Creates a unique local folder with a metadata manifest and extraction report. A ZIP download is also available. Change the output folder in Settings.</span></div><p class="help">Original uses encoded bytes when safe; edited or rendered regions use PNG. Higher rendering DPI cannot add detail to a raster source.</p>
 </div><div class="modal-foot"><button onclick={onclose}>Cancel</button><button class="primary" onclick={submit} disabled={!from||!to||from>to||to>job.total}><Download size={16}/>Export photographs</button></div></div></div>
